content.query:
let callers = datatable(Oid: string, Caller: string) [ __CALLERS__ ];
let tokenLimit = __TOKEN_LIMIT__;
let requestLimit = __REQUEST_LIMIT__;
let near = __NEAR_PERCENT__ / 100.0;
OTelLogs
| extend Oid = tolower(tostring(Attributes['azure.ai_gateway.identity.claims.oid'])), Prompt = coalesce(tolong(Attributes['azure.ai_gateway.client.usage.prompt_tokens']), tolong(Attributes['azure.ai_gateway.client.usage.input_tokens'])), Completion = coalesce(tolong(Attributes['azure.ai_gateway.client.usage.completion_tokens']), tolong(Attributes['azure.ai_gateway.client.usage.output_tokens']))
| where isnotnull(Prompt) or isnotnull(Completion)
| summarize TokensPerMinute = sum(coalesce(Prompt, long(0)) + coalesce(Completion, long(0))), RequestsPerMinute = count() by Oid, Minute = bin(TimeGenerated, 1m)
| where TokensPerMinute >= near * tokenLimit or RequestsPerMinute >= near * requestLimit
| lookup kind=leftouter callers on Oid
| extend Caller = iff(isempty(Caller), strcat('not on the access list, ', substring(Oid, 0, 8)), Caller)
| project Minute, Caller, TokensPerMinute, RequestsPerMinute, ['Token limit'] = tokenLimit, ['Request limit'] = requestLimit
| order by Minute desc
